//! What `protocolgen` writes: the TypeScript declarations of every wire type,
//! and the JSON Schema of everything the server sends.
//!
//! The list of types lives here, next to the types, so a new DTO is added to
//! the generated client in the same file set that declares it.

use schemars::Schema;
use schemars::generate::SchemaSettings;
use schemars::transform::{Transform, transform_subschemas};
use serde_json::Value;
use ts_rs::TS;

use crate::{client::*, dto::*, enums::*, server::*};

/// The header both generated files open with.
pub fn header(what: &str) -> String {
    format!(
        "// Code generated by server-rs/crates/protocolgen. DO NOT EDIT.\n\
         //\n\
         // Source: server-rs/crates/loco-protocol. Regenerate with \"make protocol\"; CI\n\
         // fails the build if this file and the Rust source have drifted apart, so\n\
         // editing it by hand is undone by the next run rather than merged.\n\
         //\n\
         // This file carries {what}.\n"
    )
}

fn decl<T: TS>(out: &mut String) {
    out.push('\n');
    if let Some(docs) = T::docs() {
        out.push_str(&docs);
    }
    out.push_str("export ");
    out.push_str(&T::decl());
    out.push('\n');
}

/// `src/types/protocol.ts`.
pub fn typescript() -> String {
    let mut out = header("the protocol's TypeScript types");

    // The wire enums.
    decl::<CardColor>(&mut out);
    decl::<CardKind>(&mut out);
    decl::<MatchFormat>(&mut out);
    decl::<Emote>(&mut out);

    // The records.
    decl::<CardDTO>(&mut out);
    decl::<CatchSeatDTO>(&mut out);
    decl::<ScoreboardEntryDTO>(&mut out);
    decl::<MatchRecordDTO>(&mut out);
    decl::<LatencyEntryDTO>(&mut out);
    decl::<PlayerDTO>(&mut out);
    decl::<GameEventDTO>(&mut out);
    decl::<GameStateDTO>(&mut out);
    decl::<LiveStreamDTO>(&mut out);
    decl::<DebugStateDTO>(&mut out);
    decl::<DebugHandOverrideDTO>(&mut out);

    // Client to server.
    decl::<ClientMsg>(&mut out);
    decl::<NicknameMsg>(&mut out);
    decl::<JoinRoomMsg>(&mut out);
    decl::<SetMatchFormatMsg>(&mut out);
    decl::<SetMaxPlayersMsg>(&mut out);
    decl::<SetStreamerModeMsg>(&mut out);
    decl::<TargetMsg>(&mut out);
    decl::<SendEmoteMsg>(&mut out);
    decl::<PlayCardMsg>(&mut out);
    decl::<CounterDrawMsg>(&mut out);
    decl::<InterruptPlayMsg>(&mut out);
    decl::<DebugSetStateMsg>(&mut out);

    // Server to client.
    decl::<ServerMsg>(&mut out);
    decl::<EmptyMsg>(&mut out);
    decl::<RoomCreatedMsg>(&mut out);
    decl::<RoomJoinedMsg>(&mut out);
    decl::<PlayerJoinedMsg>(&mut out);
    decl::<PlayerLeftMsg>(&mut out);
    decl::<PlayerDisconnectedMsg>(&mut out);
    decl::<PlayerReconnectedMsg>(&mut out);
    decl::<LobbyConfigChangedMsg>(&mut out);
    decl::<StreamerModeChangedMsg>(&mut out);
    decl::<GameStartedMsg>(&mut out);
    decl::<MatchFoundMsg>(&mut out);
    decl::<HostChangedMsg>(&mut out);
    decl::<MatchLoadingMsg>(&mut out);
    decl::<MatchReadyMsg>(&mut out);
    decl::<GameStateMsg>(&mut out);
    decl::<CardPlayedMsg>(&mut out);
    decl::<CardDrawnMsg>(&mut out);
    decl::<TurnChangedMsg>(&mut out);
    decl::<SeatMsg>(&mut out);
    decl::<CatchLockedMsg>(&mut out);
    decl::<InterruptSuccessMsg>(&mut out);
    decl::<RoundEndMsg>(&mut out);
    decl::<MatchEndMsg>(&mut out);
    decl::<LatencyMsg>(&mut out);
    decl::<EmoteMsg>(&mut out);
    decl::<RematchOfferedMsg>(&mut out);
    decl::<RematchStartedMsg>(&mut out);
    decl::<PlayersOnlineMsg>(&mut out);
    decl::<LiveStreamsMsg>(&mut out);
    decl::<ErrorMsg>(&mut out);

    // The two discriminants, by name: the client keys tables on them.
    out.push_str(
        "\n/** Every `type` a client can send. */\n\
         export type ClientMsgType = ClientMsg['type'];\n\
         \n/** Every `type` the server can send. */\n\
         export type ServerMsgType = ServerMsg['type'];\n\
         \n/** One server message, narrowed to its `type`. */\n\
         export type ServerMsgOf<T extends ServerMsgType> = Extract<ServerMsg, { type: T }>;\n",
    );
    out
}

/// The JSON Schema of [`ServerMsg`], which `tools/protocol/valibot.mjs` turns
/// into the client's inbound validators.
///
/// An optional property's `Option<T>` is spelled as `T` (see [`AbsentNotNull`]).
pub fn server_schema() -> serde_json::Value {
    let generator = SchemaSettings::draft2020_12()
        .with_transform(AbsentNotNull)
        .into_generator();
    let schema = generator.into_root_schema_for::<ServerMsg>();
    serde_json::to_value(schema).expect("a schema is always JSON")
}

/// Takes `null` out of every property that is not `required`.
///
/// `schemars` spells `Option<T>` as "`T` or `null`", which is what serde would
/// read. It is not what this server writes: every `Option` in this crate is
/// skipped when it is `None`, so an optional field is absent or a `T`, never a
/// `null`. Left in, the null would make the generated validator looser than
/// the wire and disagree with the TypeScript type `ts-rs` writes (`x?: T`).
///
/// A *required* property that admits `null` is left alone, and the converter
/// refuses it: that would be a field this crate writes as `null`, which no
/// client type here spells.
#[derive(Clone)]
struct AbsentNotNull;

impl Transform for AbsentNotNull {
    fn transform(&mut self, schema: &mut Schema) {
        transform_subschemas(self, schema);
        let Some(obj) = schema.as_object_mut() else {
            return;
        };
        let required: Vec<String> = obj
            .get("required")
            .and_then(Value::as_array)
            .map(|r| {
                r.iter()
                    .filter_map(|v| v.as_str().map(str::to_owned))
                    .collect()
            })
            .unwrap_or_default();
        let Some(Value::Object(props)) = obj.get_mut("properties") else {
            return;
        };
        for (name, prop) in props.iter_mut() {
            if !required.contains(name) {
                drop_null(prop);
            }
        }
    }
}

fn is_null_schema(v: &Value) -> bool {
    v.as_object()
        .is_some_and(|o| o.len() == 1 && o.get("type") == Some(&Value::from("null")))
}

fn drop_null(prop: &mut Value) {
    let Some(obj) = prop.as_object_mut() else {
        return;
    };
    // `"type": ["integer", "null"]`
    if let Some(Value::Array(types)) = obj.get_mut("type") {
        types.retain(|t| t != "null");
        if types.len() == 1 {
            let only = types.remove(0);
            obj.insert("type".to_owned(), only);
        }
    }
    // `"anyOf": [{"$ref": ...}, {"type": "null"}]`
    let pair = match obj.get("anyOf") {
        Some(Value::Array(any)) if any.len() == 2 && any.iter().any(is_null_schema) => {
            any.iter().find(|s| !is_null_schema(s)).cloned()
        }
        _ => None,
    };
    if let Some(Value::Object(inner)) = pair {
        obj.remove("anyOf");
        for (k, v) in inner {
            obj.entry(k).or_insert(v);
        }
    }
}
